mapper.select:
select
a.preset_id,
preset_num,
a.robot_id,
a.robot_code,
a.preset_name,
a.creator_time,
a.remark
from t_robot_camera_preset a
where 1 = 1
 and a.preset_id = #{presetId, jdbcType=BIGINT}
 and a.preset_num = #{presetNum, jdbcType=INTEGER}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.robot_code = #{robotCode, jdbcType=VARCHAR}
 and a.preset_name = #{presetName, jdbcType=VARCHAR}
 and a.creator_time = #{creatorTime, jdbcType=TIMESTAMP}
 and a.remark = #{remark, jdbcType=VARCHAR}

